# Soufflé input-relation -> library IR CSV basename (concatenated across all library modules).
# run-souffle.sh scopes these to signature relations (LIB_SIG); bodies are never staged.
lib_annotation	all-annotations
lib_annotation_argument	all-annotation-arguments
lib_block	all-blocks
lib_enum_constant	all-enum-constants
lib_expression	all-expressions
lib_field	all-fields
lib_field_position	all-field-positions
lib_import	all-imports
lib_local_variable	all-local-variables
lib_method	all-methods
# build config that decides the generated API's NAMES (lombok.config). Nothing reads a
# library's APPLICATION config: every consumer of prop_key/prop_segment is scoped to
# "client" on purpose, because a dependency's own yml configures the dependency.
lib_property_key	all-property-keys
lib_property_value_segment	all-property-value-segments
lib_method_parameter	all-method-parameters
lib_method_type_parameter	all-method-type-parameters
lib_type	all-types
lib_type_lines	all-types
lib_type_parameter	all-type-parameters
lib_type_reference	all-type-references
lib_service_descriptor	all-service-descriptors
lib_service_provider	all-service-providers
